#!/usr/bin/env node
/**
 * Golden files of the probes (card T3.4): small, committed, derived from a probes folder (probes/ of a fixture).
 *
 *   node golden.mjs make  PROBES_DIR  GOLDEN_DIR      writes GOLDEN_DIR/<scenario>/A<n>.json.gz (per area), tapes.json.gz, draws.json.gz (gzipped JSON)
 *   node golden.mjs check PROBES_DIR  GOLDEN_DIR      regenerates nothing: compares a probes folder with the committed goldens (exit 1 if different)
 *
 * What a golden keeps (everything else is regenerated by run-probes.mjs into the scratchpad):
 *   per area, per probe, per window: the call count, the number of recorded calls, `chain` (FNV-1a 32 of the JSON of every recorded record, raw
 *     file names left out, so a TypeScript regeneration can be compared in one number) and the first two records in full;
 *   tapes: per step the 8-digit hash of the JSON of its steps / environment / air entries, the generator draw counters, the hash of each ember log;
 *   draws: the standalone generator goldens and table hashes, the first draws of each stream, the draw counts per consumer, the per-particle
 *     draw-count histogram and the first ember events.
 */
import { mkdirSync, readFileSync, readdirSync, writeFileSync, existsSync } from 'node:fs';
import { join } from 'node:path';
import { fileURLToPath } from 'node:url';
import { gunzipSync, gzipSync } from 'node:zlib';
import { fnvHex, openProbes } from './reader.mjs';

const enc = new TextEncoder();
/** Goldens are written gzipped (JSON, level 9, no timestamp: the bytes are reproducible): about a tenth of the size. */
const writeGz = (file, v) => writeFileSync(file, gzipSync(JSON.stringify(v), { level: 9 }));
const readGz = (file) => JSON.parse(gunzipSync(readFileSync(file)).toString('utf8'));
const hashJson = (v) => fnvHex(enc.encode(JSON.stringify(v)));
const strip = (rec) => {
  const { raw, rawSkipped, ...rest } = rec;
  return rest;
};
/** blob offsets depend on which arrays were stored, not on the values: leave them out of a hash. */
const noBlob = (o) => JSON.parse(JSON.stringify(o, (k, v) => (k === 'blob' ? undefined : v)));

export function makeGolden(dir, { areas: withAreas = true } = {}) {
  const p = openProbes(dir);
  const idx = p.index();
  const areas = {};
  for (const [id, pr] of withAreas ? Object.entries(idx.probes) : []) {
    const area = pr.area;
    areas[area] ??= {};
    areas[area][id] = { file: pr.file, name: pr.name, windows: {} };
  }
  const callFiles = withAreas ? readdirSync(join(dir, 'calls')).filter((f) => f.endsWith('.json')) : [];
  for (const f of callFiles) {
    const c = JSON.parse(readFileSync(join(dir, 'calls', f), 'utf8'));
    for (const [id, wins] of Object.entries(c.probes)) {
      for (const [w, list] of Object.entries(wins)) {
        const recs = list.map(strip);
        areas[c.area][id].windows[w] = { calls: idx.probes[id].windows[w].calls, recorded: recs.length, chain: hashJson(recs), first: recs.slice(0, 2) };
      }
    }
  }
  // windows with calls but no recorded record (hot probes outside the windows): counts only
  for (const [id, pr] of withAreas ? Object.entries(idx.probes) : []) {
    for (const [w, v] of Object.entries(pr.windows)) areas[pr.area][id].windows[w] ??= { calls: v.calls, recorded: 0 };
  }
  const steps = p.steps().steps;
  const env = p.envTape().steps;
  const air = p.airTape();
  const emberLogs = {};
  for (const [k, v] of Object.entries(air.ember)) {
    const f = join(dir, v.file);
    emberLogs[k] = { records: v.records, truncated: v.truncated, h: existsSync(f) ? fnvHex(readFileSync(f)) : null };
  }
  const tapes = {
    scenario: idx.scenario,
    seed: idx.seed,
    steps: steps.map((s) => [s.k, s.t, hashJson(s), s.draws]),
    env: env.map((s) => [s.k, hashJson(noBlob(s))]),
    air: air.steps.map((s) => [s.k, hashJson(noBlob(s))]),
    emberLogs,
    landing: Object.fromEntries(Object.entries(air.landing).map(([w, l]) => [w, { n: l.length, h: hashJson(l) }])),
    ignite: Object.fromEntries(Object.entries(air.ignite).map(([w, l]) => [w, { n: l.length, h: hashJson(l) }])),
    callSequence: Object.fromEntries(['init', 'spin', 'w0', 'w600', 'w900'].map((w) => [w, { n: idx.callSequence[w].length, h: hashJson(idx.callSequence[w].map((i) => idx.callSequence.names[i])) }])),
  };
  const d = p.draws();
  const draws = {
    scenario: d.scenario,
    seed: d.seed,
    embers: d.embers,
    totals: d.streams.totals,
    ember: { ...d.streams.embers, firstViaFastRng: d.streams.embers.firstViaFastRng.slice(0, 64) },
    fire: d.streams.fire && { ...d.streams.fire, first: d.streams.fire.first.slice(0, 64) },
    atmosphere: d.streams.atmosphere,
    emberEvents: d.emberEvents.slice(0, 40),
    emberEventsCount: d.emberEvents.length,
    perParticleAdvance: { histogram: d.perParticleAdvance.histogram, firstPairs: Object.fromEntries(Object.entries(d.perParticleAdvance.pairs).map(([w, l]) => [w, l.slice(0, 200)])) },
  };
  const generators = { standalone: d.standalone, tables: d.tables };
  return { scenario: idx.scenario, areas, tapes, draws, generators };
}

export function writeGolden(dir, out, opts = {}) {
  const g = makeGolden(dir, opts);
  const base = join(out, g.scenario);
  mkdirSync(base, { recursive: true });
  for (const [a, probes] of Object.entries(g.areas)) writeGz(join(base, `${a}.json.gz`), { area: a, scenario: g.scenario, probes });
  writeGz(join(base, 'tapes.json.gz'), g.tapes);
  writeGz(join(base, 'draws.json.gz'), g.draws);
  if (opts.generators) writeGz(join(out, 'generators.json.gz'), g.generators);
  return g;
}

/** Compares a regenerated probes folder with the committed goldens; returns the list of differences (empty: identical). */
export function checkGolden(dir, goldenDir, opts = {}) {
  const g = makeGolden(dir, opts);
  const base = join(goldenDir, g.scenario);
  const bad = [];
  const read = (f) => readGz(join(base, `${f}.gz`));
  for (const [a, probes] of Object.entries(g.areas)) {
    const want = read(`${a}.json`).probes;
    for (const [id, pr] of Object.entries(probes)) {
      for (const [w, v] of Object.entries(pr.windows)) {
        const x = want[id]?.windows?.[w];
        if (!x || x.calls !== v.calls || x.recorded !== v.recorded || x.chain !== v.chain) bad.push(`${id} ${w}: calls ${v.calls} vs ${x?.calls}, chain ${v.chain} vs ${x?.chain}`);
      }
    }
  }
  const t = read('tapes.json');
  if (JSON.stringify(t) !== JSON.stringify(g.tapes)) bad.push('tapes.json differs');
  const d = read('draws.json');
  if (JSON.stringify(d) !== JSON.stringify(g.draws)) bad.push('draws.json differs');
  if (opts.generators && JSON.stringify(readGz(join(goldenDir, 'generators.json.gz'))) !== JSON.stringify(g.generators)) bad.push('generators.json differs');
  return bad;
}

if (process.argv[1] === fileURLToPath(import.meta.url)) {
  const [cmd, dir, out] = process.argv.slice(2);
  if (cmd === 'make' && dir && out) {
    const g = writeGolden(dir, out);
    console.log(`golden ${g.scenario}: ${Object.keys(g.areas).length} areas written to ${join(out, g.scenario)}`);
  } else if (cmd === 'check' && dir && out) {
    const bad = checkGolden(dir, out);
    console.log(bad.length ? `DIFFERENT (${bad.length}):\n${bad.slice(0, 30).join('\n')}` : 'identical');
    process.exit(bad.length ? 1 : 0);
  } else {
    console.error('usage: node golden.mjs make|check PROBES_DIR GOLDEN_DIR');
    process.exit(2);
  }
}
